import{_ as e,o,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Webhooks","description":"Automatically notify other systems about changes in a Grid.","frontmatter":{"title":"Webhooks","description":"Automatically notify other systems about changes in a Grid."},"headers":[],"relativePath":"en/integrationen/webhooks.md","filePath":"en/integrationen/webhooks.md","lastUpdated":1787319236000}'),s={name:"en/integrationen/webhooks.md"};function i(n,t,d,l,h,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h1><p>A <strong>webhook</strong> notifies an outside system when something happens in a Grid.</p><p>The description in the interface:</p><blockquote><p><em>Webhooks are automatic messages sent when something happens. They carry a message or payload and are sent to a unique URL.</em></p></blockquote><div class="warning custom-block"><p class="custom-block-title">Two directions, two places</p><table tabindex="0"><thead><tr><th>Direction</th><th>Set up in</th></tr></thead><tbody><tr><td><strong>ApptiveGrid → outside system</strong></td><td>Space settings → Webhooks — this page</td></tr><tr><td><strong>Outside system → ApptiveGrid</strong></td><td><a href="/en/flows/webhook-trigger">Flow trigger <em>Webhook</em></a></td></tr></tbody></table><p>Both are called &quot;webhook&quot;, but they do opposite things.</p></div><h2 id="creating-a-webhook" tabindex="-1">Creating a webhook <a class="header-anchor" href="#creating-a-webhook" aria-label="Permalink to &quot;Creating a webhook&quot;">​</a></h2><ol><li>Open <strong>Space settings → Webhooks</strong>.</li><li>Click <strong>Create webhook</strong>.</li><li>Give it a name under <strong>Webhook name</strong>. The default is <em>My Webhook</em>.</li><li>Set the event under <strong>Trigger the Flow when</strong>.</li><li>Enter the target URL and click <strong>Save</strong>.</li></ol><p>Via <strong>Edit</strong> and <strong>Delete</strong>, you manage existing webhooks.</p><div class="tip custom-block"><p class="custom-block-title">Name it descriptively</p><p>With several webhooks, &quot;My Webhook&quot; doesn&#39;t say anything. Name it after its target and purpose — &quot;Inventory system: new order&quot;.</p></div><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>Trigger</th><th>Additional selection</th></tr></thead><tbody><tr><td><strong>New entry</strong></td><td>An entry is created</td><td>Space, Grid</td></tr><tr><td><strong>Entry changed</strong></td><td>An entry is changed</td><td>Space, Grid</td></tr><tr><td><strong>New entry via form</strong></td><td>A form creates one</td><td>Space, Grid, form</td></tr><tr><td><strong>Entry changed via form</strong></td><td>A form changes one</td><td>Space, Grid, form</td></tr></tbody></table><p>Via <strong>Select Space</strong>, <strong>Select Grid</strong>, <strong>Select event</strong>, and <strong>Select form</strong>, you narrow it down.</p><div class="warning custom-block"><p class="custom-block-title">Deprecated events</p><p>Older webhooks may use events marked <strong>deprecated</strong> in the dialog. They keep working, but should be replaced when you revise them.</p></div><h2 id="webhook-or-flow" tabindex="-1">Webhook or Flow? <a class="header-anchor" href="#webhook-or-flow" aria-label="Permalink to &quot;Webhook or Flow?&quot;">​</a></h2><p>Both react to the same events. The difference:</p><table tabindex="0"><thead><tr><th></th><th>Webhook</th><th><a href="/en/flows/was-ist-ein-flow">Flow</a></th></tr></thead><tbody><tr><td>Purpose</td><td>Pass along raw data</td><td>Do something</td></tr><tr><td>Logic</td><td>none</td><td>conditions, loops, multiple steps</td></tr><tr><td>Recipient</td><td>one system</td><td>any number of actions</td></tr><tr><td>Requirement</td><td>recipient can process JSON</td><td>–</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">For most cases, a Flow is the right approach</p><p>A webhook just forwards data. If you want to <strong>filter</strong> (&quot;only for amounts over €1000&quot;), <strong>enrich</strong>, or <strong>trigger multiple things</strong>, you need a Flow — there, the <strong>HTTP request</strong> step is the counterpart to a webhook, but with logic in front of it.</p><p>A webhook is worth it when a system simply needs to be notified of every change.</p></div><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Number per Space depends on your plan</p><p>Once the limit is reached, <em>Create more webhooks</em> appears with an upgrade prompt.</p></div><div class="warning custom-block"><p class="custom-block-title">No delivery tracking in the interface</p><p>Unlike <a href="/en/flows/durchlaufhistorie">Flow runs</a>, there&#39;s no history showing whether a webhook arrived. If delivery fails, you&#39;ll only notice it at the target system.</p><p>Where traceability matters, a Flow is the better choice — there you can see every run along with any errors.</p></div><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">The target URL receives your data</p><p>The webhook sends the content of the entry to the address you entered. Check:</p><ul><li>Is the address correct and current?</li><li>Is it transmitted over HTTPS?</li><li>Is the recipient even allowed to receive this data?</li></ul><p>For personal data, this needs a data protection review.</p></div><div class="tip custom-block"><p class="custom-block-title">Remove webhooks you no longer need</p><p>A webhook keeps firing even if the target system was shut down long ago. Review the list regularly — especially after system changes.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/integrationen/ueberblick">Overview</a></li><li><a href="/en/flows/webhook-trigger">Starting a Flow via webhook</a></li><li><a href="/en/flows/aktionen">Actions</a></li></ul>',25)])])}const b=e(s,[["render",i]]);export{g as __pageData,b as default};
